- **공고명:** 크래프톤 게임 QA 멀티에이전트 엔지니어 채용
- **직무명:** 게임 QA 멀티에이전트 엔지니어
- **모집인원:** 1~2명
- **경력:** 관련 경력 3년 이상
- **학력:** 학사 이상

### 2. 회사 / 직무 소개
- **회사 또는 고객사 소개:** 크래프톤은 온라인 게임과 관련 디지털 콘텐츠를 개발·서비스하는 기업
- **직무 소개:** 테스트 계획 생성·로그 분석·재현 절차 작성 에이전트를 협업시키고 결과를 검수 가능하게 만든다. AI가 단독으로 최종 결정을 내리는 대신, 업무 도구·데이터·사람 검토를 연결하는 오케스트레이션을 담당한다.

### 3. 담당업무
- 테스트 계획 생성·로그 분석·재현 절차 작성 에이전트를 협업시키고 결과를 검수 가능하게 만든다.
- 게임·디지털 콘텐츠의 데이터와 기존 시스템을 연계하고, 실패·예외 상황에서 담당자가 개입할 경로를 구현한다.
- 실행 기록과 품질 지표를 수집해 멀티에이전트 설계 흐름의 정확도·응답시간·운영 부담을 개선한다.

### 4. 자격요건
- 서비스 구성요소의 역할과 인터페이스를 설계한 경험
- 실패·중복 실행·상충 결과를 다루는 설계 역량
- 한 가지 이상 프로그래밍 언어로 백엔드 또는 데이터 시스템을 구현한 경험

### 5. 우대사항
- 분산 시스템이나 메시지 큐 이해
- 에이전트 평가 또는 협업형 자동화 실험 경험

### 6. 제출서류
- **이력서:** 자유 양식 이력서(PDF 권장), 관련 프로젝트·기여 내용 기재

### 7. 지원 방법
- **접수 방법:** 온라인 지원 페이지

### 8. 접수기간
- **접수 마감:** 채용 시 마감

### 9. 채용절차
- 서류전형
- 면접(직무 인터뷰 포함 가능)
- 최종합격

### 10. 근무조건
- **고용형태:** 정규직(수습기간 협의)
- **급여:** 면접 후 협의
- **근무지:** 서울 또는 경기(협의)
- **근무요일/시간:** 주 5일, 10:00~19:00

### 11. 유의사항
- 지원 자료에 이전 직장·고객사의 기밀정보나 개인정보를 포함하지 마세요.

