### 1. 기본 정보
- **회사명:** CJ ENM
- **공고명:** CJ ENM 콘텐츠 제작 워크플로 오케스트레이터 채용
- **직무명:** 콘텐츠 제작 워크플로 오케스트레이터
- **모집인원:** 2명
- **경력:** 관련 경력 2년 이상
- **학력:** 전문학사 이상

### 2. 회사 / 직무 소개
- **회사 또는 고객사 소개:** CJ ENM은 방송, 영화, 음악, 공연 및 콘텐츠 유통 사업을 전개하는 기업
- **직무 소개:** 기획 자료 탐색, 초안 작성, 권리 확인, 편집 검토 단계를 사람 승인과 함께 연결한다. AI가 단독으로 최종 결정을 내리는 대신, 업무 도구·데이터·사람 검토를 연결하는 오케스트레이션을 담당한다.

### 3. 담당업무
- 기획 자료 탐색, 초안 작성, 권리 확인, 편집 검토 단계를 사람 승인과 함께 연결한다.
- 미디어·엔터테인먼트·콘텐츠의 데이터와 기존 시스템을 연계하고, 실패·예외 상황에서 담당자가 개입할 경로를 구현한다.
- 실행 기록과 품질 지표를 수집해 에이전트·워크플로 흐름의 정확도·응답시간·운영 부담을 개선한다.

### 4. 자격요건
- 에이전트 실행 흐름과 외부 도구 연동 경험
- 상태 관리, 재시도, 권한 검사 중 하나 이상을 실제 코드로 구현한 경험
- Python 또는 TypeScript로 API 기반 서비스를 개발한 경험

### 5. 우대사항
- 비동기 작업·워크플로 엔진 사용 경험
- LLM 함수 호출 또는 업무 자동화 프로젝트 경험

### 6. 제출서류
- **이력서:** 자유 양식 이력서(PDF 권장), 관련 프로젝트·기여 내용 기재

### 7. 지원 방법
- **접수 방법:** 온라인 지원 페이지

### 8. 접수기간
- **접수 마감:** 채용 시 마감

### 9. 채용절차
- 서류전형
- 면접(직무 인터뷰 포함 가능)
- 최종합격

### 10. 근무조건
- **고용형태:** 계약직 1년 후 평가
- **급여:** 경력에 따라 협의
- **근무지:** 경기
- **근무요일/시간:** 주 5일, 근무시간 협의

### 11. 유의사항
- 지원 자료에 이전 직장·고객사의 기밀정보나 개인정보를 포함하지 마세요.

