- **공고명:** 비트컴퓨터 IT 운영 RAG 엔지니어 채용
- **직무명:** IT 운영 RAG 엔지니어
- **모집인원:** 3명 내외
- **경력:** 신입 지원 가능(포트폴리오 권장)
- **학력:** 관련 분야 학사 이상 또는 이에 준하는 경험

### 2. 회사 / 직무 소개
- **회사 또는 고객사 소개:** 비트컴퓨터은 의료정보 시스템과 관련 소프트웨어, IT 교육 사업을 영위하는 기업
- **직무 소개:** 장애 이력과 운영 매뉴얼을 연결해 과거 조치 근거를 찾고 답변에 출처를 표시한다. AI가 단독으로 최종 결정을 내리는 대신, 업무 도구·데이터·사람 검토를 연결하는 오케스트레이션을 담당한다.

### 3. 담당업무
- 장애 이력과 운영 매뉴얼을 연결해 과거 조치 근거를 찾고 답변에 출처를 표시한다.
- 의료정보 소프트웨어·교육의 데이터와 기존 시스템을 연계하고, 실패·예외 상황에서 담당자가 개입할 경로를 구현한다.
- 실행 기록과 품질 지표를 수집해 RAG·데이터 흐름의 정확도·응답시간·운영 부담을 개선한다.

### 4. 자격요건
- 문서·정형 데이터 수집 및 검색 시스템을 다룬 경험
- 검색 결과와 답변의 근거·최신성을 점검하는 역량
- Python과 SQL을 사용한 데이터 처리 경험

### 5. 우대사항
- 벡터 검색·하이브리드 검색 튜닝 경험
- 도메인 지식베이스 구축 또는 평가 경험

### 6. 제출서류
- **이력서:** 자유 양식 이력서(PDF 권장), 관련 프로젝트·기여 내용 기재

### 7. 지원 방법
- **접수 방법:** 온라인 지원 페이지

### 8. 접수기간
- **접수 마감:** 채용 시 마감

### 9. 채용절차
- 서류전형
- 면접(직무 인터뷰 포함 가능)
- 최종합격

### 10. 근무조건
- **고용형태:** 정규직 또는 계약직 협의
- **급여:** 직무·경력에 따라 협의
- **근무지:** 근무지 협의
- **근무요일/시간:** 근무요일·시간 협의

### 11. 유의사항
- 지원 자료에 이전 직장·고객사의 기밀정보나 개인정보를 포함하지 마세요.

