### 3. 담당업무
- 프롬프트 공격과 오답 사례를 설계해 모델·도구 조합의 취약점을 반복 평가한다.
- 통신 소프트웨어·부가서비스의 데이터와 기존 시스템을 연계하고, 실패·예외 상황에서 담당자가 개입할 경로를 구현한다.
- 실행 기록과 품질 지표를 수집해 평가·품질 흐름의 정확도·응답시간·운영 부담을 개선한다.

