  ('099.md', '## 099. 음성 AI 평가 데이터 매니저

### 1. 기본 정보
- **회사명:** 셀바스AI
- **공고명:** 셀바스AI 음성 AI 평가 데이터 매니저 채용
- **직무명:** 음성 AI 평가 데이터 매니저
- **모집인원:** 3명 내외
- **경력:** 신입 지원 가능(포트폴리오 권장)
- **학력:** 관련 분야 학사 이상 또는 이에 준하는 경험

### 2. 회사 / 직무 소개
- **회사 또는 고객사 소개:** 셀바스AI은 음성인식·음성합성 등 AI 기술과 헬스케어 관련 소프트웨어를 개발하는 기업
- **직무 소개:** 화자·소음·억양 조건을 포함한 평가 데이터를 관리하고 인식·응답 품질을 분석한다. AI가 단독으로 최종 결정을 내리는 대신, 업무 도구·데이터·사람 검토를 연결하는 오케스트레이션을 담당한다.

### 3. 담당업무
- 화자·소음·억양 조건을 포함한 평가 데이터를 관리하고 인식·응답 품질을 분석한다.
- 음성 AI·헬스케어 소프트웨어의 데이터와 기존 시스템을 연계하고, 실패·예외 상황에서 담당자가 개입할 경로를 구현한다.
- 실행 기록과 품질 지표를 수집해 평가·품질 흐름의 정확도·응답시간·운영 부담을 개선한다.

### 4. 자격요건
- 기능 또는 모델 품질 평가 기준을 설계한 경험
- 정량 지표와 정성 검토를 함께 사용해 결과를 해석하는 역량
- Python 기반 데이터 분석 및 테스트 자동화 역량

### 5. 우대사항
- LLM 평가셋·레드팀 평가 경험
- 도메인별 품질 기준 운영 경험

### 6. 제출서류
