INSERT INTO public.job_postings (title, description, responsibilities, requirements, preferred_requirements, source_name, source_external_id)
SELECT
  COALESCE(NULLIF((regexp_match(description, '(?m)^\s*-\s+\*\*공고명:\*\*\s*(.*?)\s*$'))[1], ''), '시연용 채용공고'),
  description, responsibilities, requirements, preferred_requirements, 'local_markdown', source_external_id
FROM fixture
ON CONFLICT (source_name, source_external_id) WHERE source_name IS NOT NULL AND source_external_id IS NOT NULL DO NOTHING;

COMMIT;

-- Verify the loaded demo postings:
SELECT COUNT(*) AS demo_posting_count
FROM public.job_postings
WHERE source_name = 'local_markdown'
  AND source_external_id ~ '^[0-9]{3}\.md$';

